{
  "claims": [
    {
      "kind": "qualitative",
      "text": "Walmart operates as an omnichannel retailer through three business segments—Walmart U.S., Walmart International and Sam's Club U.S.—serving customers through stores, eCommerce websites and mobile applications.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0016",
          "quote": "We are enhancing our omnichannel capabilities through a combination of stores, eCommerce websites, mobile applications and service offerings"
        },
        {
          "chunk_id": "WMT-000010416926000055-0148",
          "quote": "financial results of each of the three segments of our business"
        },
        {
          "chunk_id": "WMT-000010416926000055-0031",
          "quote": "we began combining the Sam's Club U.S. supply chain function with Walmart U.S."
        },
        {
          "chunk_id": "WMT-000010416926000055-0023",
          "quote": "The merchandising strategy for Walmart International is similar to that of our operations in the U.S."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart's business continues to expand through offerings such as membership, advertising, marketplace and fulfillment services, and financial services.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0016",
          "quote": "our business continues to expand through offerings such as membership, advertising, marketplace and fulfillment services, and financial services"
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Walmart's revenue was {{m:revenue:FY-2}} in {{p:FY-2}}, {{m:revenue:FY-1}} in {{p:FY-1}}, {{m:revenue:FY0}} in {{p:FY0}} and {{m:revenue:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA was {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "Walmart's operations outside the U.S. include distribution facilities strategically located in Africa, Canada, Central America, Chile, China, India and Mexico.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0031",
          "quote": "Outside the U.S., we utilize a total of 179 distribution facilities strategically located in Africa, Canada, Central America, Chile, China, India and Mexico"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart's business is seasonal to a certain extent, and historically its highest sales volume for each segment has occurred in the fourth quarter of the fiscal year.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0029",
          "quote": "Our business is seasonal to a certain extent and varies by country"
        },
        {
          "chunk_id": "WMT-000010416926000055-0029",
          "quote": "Historically, our highest sales volume for each segment has occurred in the fourth quarter of our fiscal year"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt / EBITDA was stable, at {{m:debt_to_ebitda:FY-2}} in {{p:FY-2}} and {{m:debt_to_ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Net leverage was also stable, moving from {{m:net_leverage:FY-2}} in {{p:FY-2}} to {{m:net_leverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA / interest improved from {{m:interest_coverage:FY-2}} in {{p:FY-2}} to {{m:interest_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "FCF / debt worsened from {{m:fcf_to_debt:FY-2}} in {{p:FY-2}} to {{m:fcf_to_debt:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The weakening FCF / debt trend reflects higher capital spending to support the omnichannel growth strategy, while total debt rose on long-term debt issuance.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0052",
          "quote": "Total Capital Expenditures $ 14,181 $ 11,409"
        },
        {
          "chunk_id": "WMT-000010416926000055-0166",
          "quote": "increase of $2.9 billion in capital expenditures to support our omnichannel growth strategy"
        },
        {
          "chunk_id": "WMT-000010416926000055-0187",
          "quote": "Our total outstanding long-term debt increased $2.2 billion during fiscal 2026, primarily due to issuances of long-term debt."
        },
        {
          "chunk_id": "WMT-000010416926000102-0063",
          "quote": "total outstanding long-term debt increased $2.6 billion, primarily due to the issuance of new long-term debt in April 2026"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The improvement in EBITDA / interest through {{p:LTM}} was supported by an approximately $2.9 billion tariff refund recorded as a reduction to cost of sales in the most recent quarter.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0043",
          "quote": "received approximately $2.9 billion in tariff refunds pursuant to the CBP process, which were recorded as a reduction to cost of sales"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Walmart's liquidity coverage was {{m:liquidity_coverage:FY0}} for {{p:FY0}} and {{m:liquidity_coverage:LTM}} for {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "For {{p:LTM}}, cash and cash equivalents were {{m:cash:LTM}}, cash from operations was {{m:cfo:LTM}}, capital expenditure was {{m:capex:LTM}}, dividends paid were {{m:dividends:LTM}}, and short-term debt was {{m:short_term_debt:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "During {{p:LTM}}, the Company renewed and extended its existing 364-day revolving credit facility of $10.0 billion as well as its five-year credit facility of $5.0 billion.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0069",
          "quote": "In April 2026, the Company renewed and extended its existing 364-day revolving credit facility of $10.0 billion as well as its five-year credit facility of $5.0 billion"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "As of {{p:LTM}}, the Company had committed lines of credit in the U.S. of $15.0 billion, all undrawn.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0069",
          "quote": "we had committed lines of credit in the U.S. of $15.0 billion at July 31, 2026, all undrawn"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "In {{p:FY0}}, scheduled long-term debt maturities are {{m:maturity_year_1:FY0}} in year one, {{m:maturity_year_2:FY0}} in year two, {{m:maturity_year_3:FY0}} in year three, {{m:maturity_year_4:FY0}} in year four, {{m:maturity_year_5:FY0}} in year five, and {{m:maturity_after_year_5:FY0}} thereafter."
    ,
    "citations": []
    }
    ,
    {
      "kind": "quantitative",
      "text": "Debt due within 24 months is {{m:debt_due_24m:FY0}}, equal to {{m:share_due_24m:FY0}} of total debt, and near-term maturity cover is {{m:near_term_maturity_cover:FY0}}."
    ,
    "citations": []
    }
    ,
    {
      "kind": "qualitative",
      "text": "Total outstanding long-term debt increased during {{p:FY0}}, primarily due to issuances of long-term debt.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0187",
          "quote": "Our total outstanding long-term debt increased $2.2 billion during fiscal 2026, primarily due to issuances of long-term debt."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The long-term notes issued during {{p:FY0}} are senior, unsecured obligations that rank equally with all other senior, unsecured debt and are not convertible or exchangeable.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0258",
          "quote": "These issuances are senior, unsecured notes which rank equally with all other senior, unsecured debt obligations of the Company, and are not convertible or exchangeable."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The issuances in {{p:FY0}} do not contain financial covenants that restrict the company's ability to pay dividends or repurchase stock.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0258",
          "quote": "These issuances do not contain any financial covenants which restrict the Company's ability to pay dividends or repurchase Company stock."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Under the committed lines of credit, the most restrictive covenant relates to the maximum amount of secured debt.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0257",
          "quote": "the Company has agreed to observe certain covenants, the most restrictive of which relates to the maximum amount of secured debt."
        }
      ]
    }
  ]
}

