{
  "claims": [
    {
      "kind": "qualitative",
      "text": "A general economic slowdown, recession or shift in consumer spending patterns in the U.S. or Walmart's other markets could lower net sales, operating income and inventory turnover, reducing cash available to service debt.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0056",
          "quote": "overall economic slowdown or recession and other economic factors in the U.S., or in any of the other markets in which we operate, could adversely affect consumer demand"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "If Walmart fails to execute its omnichannel strategy or if eCommerce and technology investment costs are excessive, its market position, net sales and financial performance could be materially weakened, reducing internal cash generation for debt repayment.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0044",
          "quote": "Failure to successfully execute our omnichannel strategy and the cost of our investments in eCommerce and technology may materially adversely affect our market position, net sales and financial performance."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart International's operations could be negatively affected by political instability, legal and regulatory constraints, antitrust matters, tax regulations and foreign-exchange rules, which could lower consolidated operating results and cash flow.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0098",
          "quote": "Our future operating results in these countries could be negatively affected by a variety of factors, most of which are beyond our control."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart's retail pharmacy earnings are exposed to government drug-price actions, payer and PBM consolidation, and changes in third-party reimbursement practices, which could reduce pharmacy profitability and cash contribution.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0090",
          "quote": "increased governmental focus on reducing drug prices including most favored nation pricing policies, maximum fair price negotiations, and direct-to-consumer pharmacy delivery models"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart's money transfer, payment, lending and cryptocurrency-related offerings are subject to anti-money laundering, sanctions, privacy and consumer protection rules, and violations could lead to fines and penalties that drain cash.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000055-0111",
          "quote": "Failure to comply with these laws and regulations could result in fines, sanctions, penalties and harm to our reputation."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "The SB grade is {{m:sb_grade:latest}}, based on a weighted score of {{m:sb_score:latest}}; the grade is not provisional, and the SB grade is a stylized internal scorecard grade, not a credit rating.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "The strongest scorecard factor is EBITDA / interest at {{m:interest_coverage:LTM}} in band {{m:band_interest_coverage:latest}} with weight {{m:weight_interest_coverage:latest}}; debt / EBITDA and net leverage also score in strong bands, at {{m:debt_to_ebitda:LTM}} in band {{m:band_debt_to_ebitda:latest}} with weight {{m:weight_debt_to_ebitda:latest}}, and {{m:net_leverage:LTM}} in band {{m:band_net_leverage:latest}} with weight {{m:weight_net_leverage:latest}}, respectively.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "The weakest scorecard factors are liquidity coverage at {{m:liquidity_coverage:LTM}} in band {{m:band_liquidity_coverage:latest}} with weight {{m:weight_liquidity_coverage:latest}}, and near-term maturity cover at {{m:near_term_maturity_cover:FY0}} in band {{m:band_near_term_maturity_cover:latest}} with weight {{m:weight_near_term_maturity_cover:latest}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "FCF / debt is a weaker mid-tier factor at {{m:fcf_to_debt:LTM}} in band {{m:band_fcf_to_debt:latest}} with weight {{m:weight_fcf_to_debt:latest}}, as higher omnichannel capital spending and long-term debt issuance temper the otherwise strong leverage profile.",
      "citations": [
        {
          "chunk_id": "WMT-000010416926000154-0052",
          "quote": "allocating the majority of our capital to higher-return areas focused on automation such as eCommerce, supply chain and store and club investments"
        },
        {
          "chunk_id": "WMT-000010416926000055-0187",
          "quote": "Our total outstanding long-term debt increased $2.2 billion during fiscal 2026, primarily due to issuances of long-term debt."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Walmart's omnichannel scale and continued expansion support the strong leverage and interest coverage bands, while the weak liquidity and near-term maturity bands temper the overall grade.",
